package com.xyz.question_bank_management_system.modules.agent.service.impl;
import com.xyz.question_bank_management_system.modules.agent.entity.ResourceBundle;
import com.xyz.question_bank_management_system.exception.*;import com.xyz.question_bank_management_system.modules.agent.entity.*;import com.xyz.question_bank_management_system.modules.agent.mapper.PersonalizedResourceMapper;import com.xyz.question_bank_management_system.modules.agent.service.ResourceAssessmentReleaseService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;
@Service @RequiredArgsConstructor public class ResourceAssessmentReleaseServiceImpl implements ResourceAssessmentReleaseService {private final PersonalizedResourceMapper mapper;@Override @Transactional public String release(Long userId,String bundleCode,String itemCode,LocalDateTime expires){ResourceBundle b=mapper.selectBundleByCode(bundleCode);if(b==null||!"PUBLISHED".equals(b.getStatus())||!Objects.equals(b.getUserId(),userId))throw BizException.of(ErrorCode.NOT_FOUND,"已发布资源不存在");ResourceItem item=mapper.selectAllItems(b.getId()).stream().filter(x->itemCode.equals(x.getItemCode())).findFirst().orElseThrow(()->BizException.of(ErrorCode.NOT_FOUND,"资源项不存在"));if(!"HIDDEN_UNTIL_ASSESSMENT".equals(item.getVisibility()))throw BizException.of(ErrorCode.PARAM_ERROR,"仅隐藏检测题需要释放");ResourceAssessmentRelease r=new ResourceAssessmentRelease();r.setReleaseCode("release_"+UUID.randomUUID().toString().replace("-",""));r.setUserId(userId);r.setBundleId(b.getId());r.setResourceItemId(item.getId());r.setStatus("ACTIVE");r.setReleasedAt(LocalDateTime.now());r.setExpiresAt(expires);mapper.insertRelease(r);return r.getReleaseCode();}@Override public List<?> active(Long userId,String bundleCode){ResourceBundle b=mapper.selectBundleByCode(bundleCode);if(b==null||!Objects.equals(b.getUserId(),userId))throw BizException.of(ErrorCode.NOT_FOUND,"资源不存在");return mapper.activeAssessments(userId,b.getId());}}
